<?php

namespace App\Http\Controllers\Api\V1;

use App\Models\{AutomationRule, AutomationRun, Company, CompanyMembership, PlatformAuditLog, PurchasingNotificationPreference, PurchasingNumberingPolicy, PurchasingSetting};
use App\Services\{AuditLogger, AuthorizationService};
use App\Support\TenantContext;
use Illuminate\Http\{JsonResponse, Request};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;

final class PurchasingSettingsController
{
    public function show(Request $request, AuthorizationService $auth): JsonResponse
    {
        $tenant=$this->tenant(); $company=$this->company($request); $this->allow($request,$auth,$tenant,$company,'view');
        $settings=PurchasingSetting::firstOrCreate(['tenant_id'=>$tenant,'company_id'=>$company],['document_language'=>'en','matching_type'=>'three_way']);
        return response()->json(['data'=>$settings,'effective'=>['company'=>$company,'branch_override'=>$request->string('branch_id')->toString()?:null]]);
    }

    public function update(Request $request, AuthorizationService $auth, AuditLogger $audit): JsonResponse
    {
        $tenant=$this->tenant(); $data=$request->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','default_branch_id'=>'nullable|uuid','default_warehouse_id'=>'nullable|uuid','default_currency_id'=>'nullable|uuid','purchasing_department_id'=>'nullable|uuid','default_purchasing_contact_id'=>'nullable|uuid','default_payment_terms'=>'nullable|string|max:100','default_tax_policy'=>'nullable|string|max:100','default_po_notes'=>'nullable|string|max:5000','default_delivery_instructions'=>'nullable|string|max:5000','po_expiry_days'=>'nullable|integer|min:0|max:3650','document_language'=>'nullable|string|max:10','receiving_approval_required'=>'boolean','over_receiving_tolerance'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'over_receiving_tolerance_unit'=>'in:percent,amount','partial_receiving_allowed'=>'boolean','quality_inspection_required'=>'boolean','damaged_goods_handling'=>'in:reject,quarantine,return','quarantine_required'=>'boolean','batch_tracking_required'=>'boolean','serial_tracking_required'=>'boolean','expiry_validation'=>'boolean','location_validation'=>'boolean','matching_type'=>'in:two_way,three_way','price_tolerance'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'price_tolerance_unit'=>'in:percent,amount','quantity_tolerance'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'quantity_tolerance_unit'=>'in:percent,amount','tax_tolerance'=>['nullable','regex:/^\d+(\.\d{1,6})?$/'],'tax_tolerance_unit'=>'in:percent,amount','matching_review_permission'=>'nullable|string|max:100']); $company=$data['company_id']; $this->allow($request,$auth,$tenant,$company,'manage'); $this->assertRefs($tenant,$data);
        $setting=DB::transaction(function()use($data,$tenant){$scope=['tenant_id'=>$tenant,'company_id'=>$data['company_id'],'branch_id'=>$data['branch_id']??null]; $setting=PurchasingSetting::where($scope)->lockForUpdate()->first(); if(!$setting)$setting=PurchasingSetting::create($scope); $setting->update([...collect($data)->except(['company_id','branch_id'])->all(),'version'=>((int)$setting->version)+1]); return $setting->fresh();}); $audit->record($request,'purchasing.settings.changed',$tenant,$setting,['company_id'=>$company,'version'=>$setting->version]); return response()->json(['data'=>$setting]);
    }

    public function numbering(Request $request, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); $company=$this->company($request); $this->allow($request,$auth,$tenant,$company,'view'); return response()->json(['data'=>PurchasingNumberingPolicy::where('tenant_id',$tenant)->where('company_id',$company)->orderBy('document_type')->get()]); }
    public function updateNumbering(Request $request, AuthorizationService $auth, AuditLogger $audit): JsonResponse
    {
        $tenant=$this->tenant(); $d=$request->validate(['company_id'=>'required|uuid','document_type'=>'required|in:PO,PR,GR,BILL,RET,SDN,SCN,PAY','prefix'=>'required|alpha_dash|max:40','include_year'=>'boolean','include_branch_code'=>'boolean','sequence_length'=>'required|integer|min:1|max:12','sequence_scope'=>'required|in:company,branch','reset_policy'=>'required|in:never,calendar_year,fiscal_year']); $this->allow($request,$auth,$tenant,$d['company_id'],'manage'); $policy=DB::transaction(function()use($d,$tenant){$p=PurchasingNumberingPolicy::where('tenant_id',$tenant)->where('company_id',$d['company_id'])->where('document_type',$d['document_type'])->lockForUpdate()->first(); if(!$p)$p=PurchasingNumberingPolicy::create([...$d,'tenant_id'=>$tenant]); else {$issued=((int)$p->next_sequence)>1; if($issued&&$p->prefix!==$d['prefix'])throw ValidationException::withMessages(['prefix'=>['Issued document numbers are immutable; use a new document policy.']]); $p->update(collect($d)->except(['company_id','document_type'])->all());} return $p->fresh();}); $audit->record($request,'purchasing.numbering.changed',$tenant,$policy,['company_id'=>$d['company_id'],'document_type'=>$d['document_type']]); return response()->json(['data'=>$policy]);
    }

    public function automations(Request $request, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); $company=$request->string('company_id')->toString()?:null; $this->allow($request,$auth,$tenant,$company,'automation'); return response()->json(['data'=>AutomationRule::where('tenant_id',$tenant)->when($company,fn($q)=>$q->where('company_id',$company))->latest()->paginate(min(max($request->integer('per_page',25),10),100))]); }
    public function storeAutomation(Request $request, AuthorizationService $auth, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); $d=$request->validate(['company_id'=>'required|uuid','branch_id'=>'nullable|uuid','rule_type'=>'required|string|max:100','event_key'=>'required|string|max:100','name'=>'required|string|max:150','conditions'=>'nullable|array','actions'=>'required|array','frequency'=>'nullable|string|max:80','timezone'=>'nullable|string|max:80','reminder_delay_minutes'=>'nullable|integer|min:0|max:525600','recipients'=>'nullable|array','channels'=>'nullable|array','is_active'=>'boolean']); $this->allow($request,$auth,$tenant,$d['company_id'],'automation'); $rule=AutomationRule::create([...$d,'tenant_id'=>$tenant,'created_by'=>$request->user()->id,'is_active'=>$d['is_active']??false]); $audit->record($request,'purchasing.automation.created',$tenant,$rule,['company_id'=>$d['company_id']]); return response()->json(['data'=>$rule],201); }
    public function updateAutomation(Request $request, AutomationRule $rule, AuthorizationService $auth, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); abort_unless($rule->tenant_id===$tenant,404); $this->allow($request,$auth,$tenant,$rule->company_id,'automation'); $d=$request->validate(['name'=>'string|max:150','conditions'=>'nullable|array','actions'=>'array','frequency'=>'nullable|string|max:80','timezone'=>'nullable|string|max:80','reminder_delay_minutes'=>'nullable|integer|min:0|max:525600','recipients'=>'nullable|array','channels'=>'nullable|array','is_active'=>'boolean']); $rule->update($d); $audit->record($request,'purchasing.automation.changed',$tenant,$rule,['company_id'=>$rule->company_id]); return response()->json(['data'=>$rule->fresh()]); }
    public function dryRun(Request $request, AutomationRule $rule, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); abort_unless($rule->tenant_id===$tenant,404); $this->allow($request,$auth,$tenant,$rule->company_id,'automation'); return response()->json(['data'=>['rule_id'=>$rule->id,'would_execute'=>false,'matched_records'=>0,'message'=>'Dry-run is read-only; no notifications or financial actions were performed.']]); }
    public function executions(Request $request, AutomationRule $rule, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); abort_unless($rule->tenant_id===$tenant,404); $this->allow($request,$auth,$tenant,$rule->company_id,'automation'); return response()->json(['data'=>AutomationRun::where('tenant_id',$tenant)->where('rule_id',$rule->id)->latest()->paginate(25)]); }

    public function preferences(Request $request, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); $company=$request->string('company_id')->toString()?:null; $this->allow($request,$auth,$tenant,$company,'view'); return response()->json(['data'=>PurchasingNotificationPreference::where('tenant_id',$tenant)->where(function($q)use($request,$company){$q->where('user_id',$request->user()->id)->orWhereNull('user_id');})->when($company,fn($q)=>$q->where(function($x)use($company){$x->whereNull('company_id')->orWhere('company_id',$company);}))->latest()->get()]); }
    public function savePreference(Request $request, AuthorizationService $auth, AuditLogger $audit): JsonResponse { $tenant=$this->tenant(); $d=$request->validate(['company_id'=>'nullable|uuid','event_type'=>'required|string|max:100','channel'=>'required|in:in_app,email','frequency'=>'required|in:immediate,daily,digest','is_enabled'=>'boolean','reminder_interval_minutes'=>'nullable|integer|min:1|max:525600']); $this->allow($request,$auth,$tenant,$d['company_id']??null,'manage'); $pref=PurchasingNotificationPreference::updateOrCreate(['tenant_id'=>$tenant,'company_id'=>$d['company_id']??null,'user_id'=>$request->user()->id,'event_type'=>$d['event_type'],'channel'=>$d['channel']],$d); $audit->record($request,'purchasing.notifications.preference.changed',$tenant,$pref,['company_id'=>$d['company_id']??null]); return response()->json(['data'=>$pref]); }
    public function auditLogs(Request $request, AuthorizationService $auth): JsonResponse { $tenant=$this->tenant(); $company=$request->string('company_id')->toString()?:null; $this->allow($request,$auth,$tenant,$company,'audit'); $q=PlatformAuditLog::where('tenant_id',$tenant)->when($company,fn($x)=>$x->whereJsonContains('metadata->company_id',$company))->when($request->filled('action'),fn($x)=>$x->where('action',$request->string('action')))->latest(); return response()->json(['data'=>$q->paginate(min(max($request->integer('per_page',25),10),100))]); }

    private function assertRefs(string $tenant,array $d):void { $company=Company::where('tenant_id',$tenant)->where('is_active',true)->findOrFail($d['company_id']); if(!empty($d['branch_id']))abort_unless(DB::table('branches')->where('id',$d['branch_id'])->where('tenant_id',$tenant)->where('company_id',$company->id)->where('is_active',true)->exists(),422); foreach(['default_branch_id','default_warehouse_id','purchasing_department_id'] as $key){if(empty($d[$key]))continue; $table=match($key){'default_branch_id'=>'branches','default_warehouse_id'=>'warehouses',default=>'departments'}; abort_unless(DB::table($table)->where('id',$d[$key])->where('tenant_id',$tenant)->where('company_id',$company->id)->exists(),422);} if(!empty($d['default_currency_id']))abort_unless(DB::table('accounting_currencies')->where('id',$d['default_currency_id'])->where('tenant_id',$tenant)->exists(),422); if(!empty($d['default_purchasing_contact_id']))abort_unless(DB::table('users')->where('id',$d['default_purchasing_contact_id'])->exists(),422);}
    private function allow(Request $r,AuthorizationService $a,string $tenant,?string $company,string $mode):void { $permissions=$mode==='automation'?['automation.manage','purchasing.settings.manage']:($mode==='audit'?['audit.view','purchasing.audit.view','organization.manage']:($mode==='manage'?['purchasing.settings.manage','procurement.manage','organization.manage']:['purchasing.settings.view','purchasing.settings.manage','procurement.manage','organization.manage'])); $allowed=false; foreach($permissions as $permission)$allowed=$allowed||$a->allows($r->user(),$tenant,$permission,$company); abort_unless($allowed,403); if($company)abort_unless(CompanyMembership::where('tenant_id',$tenant)->where('company_id',$company)->where('user_id',$r->user()->id)->where('status','active')->exists(),403); }
    private function tenant():string{return (string)app(TenantContext::class)->id();} private function company(Request $r):string{$id=$r->string('company_id')->toString(); abort_unless($id!=='',422,'company_id is required.'); return $id;}
}
